/**
 * 
 * @param {*} dateStr is never null or undefined
 * @returns undefined if the dateStr has an invalid format
 */
export function datestringToISO(dateStr){
  if(dateStr === 'live'){
    throw new Error('live');
  }

  let date;

  const now = new Date();
  if (dateStr.includes('Tomorrow')) {
    // Handle "17:00Tomorrow"
    const [time, tomorrow] = dateStr.split('Tommorow');
    const [hours, minutes] = time.split(':');
    date = new Date();
    date.setDate(date.getDate() + 1);
    date = new Date(date.getFullYear(), date.getMonth(), date.getDate(), parseInt(hours), parseInt(minutes), 0, 0);
  } else if (dateStr.includes('Today')) {
    // Handle "17:00Today"
    const [time, today] = dateStr.split('Today');
    const [hours, minutes] = time.split(':');
    date = new Date(now.getFullYear(), now.getMonth(), now.getDate(), parseInt(hours), parseInt(minutes), 0, 0);
  } else{
    // Handle "19:30Oct 20"
    // Also handle invalid string!
      const match = dateStr.match(/(\d{2}:\d{2})(.*\d{2})/);
      if(match === null || match.length !== 3){
          return undefined;
      }
    const [time, datePart] = match.slice(1);
    const [hours, minutes] = time.split(':');
    const [monthWord, day] = datePart.split(' ');
    const month = new Date(`${monthWord} 1`).getMonth(); // Convert month name to month index

    // Create a new Date object with the parsed values
    
    date = new Date(now.getFullYear(), parseInt(month), parseInt(day), parseInt(hours), parseInt(minutes), 0, 0);
  }

  if(!date){
    throw new Error('invalid data');
  } else{
    return date.toISOString();
  }
}
